<?php declare(strict_types=1); namespace App\Modules\Tourism\Controllers; use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use RuntimeException;use Throwable;use App\Modules\Tourism\Services\TourismEventService; final class TourismEventController extends Controller{private TourismEventService $s;private Authorization $a;public function __construct(){$this->s=new TourismEventService();$this->a=new Authorization();}private function allow($p,$r='/tourism'){try{$this->a->authorize($p);return true;}catch(RuntimeException $e){flash('error',$e->getMessage());redirect($r);return false;}}public function index(){if(!$this->allow('tourism.events.view'))return;$t=(int)Auth::tenantId();$trash=($_GET['view']??'')==='trash';$this->view('Tourism::Events.index',['title'=>$trash?'Deleted Events':'Events & Festivals','events'=>$this->s->all($t,$trash),'trash'=>$trash]);}public function create(){if(!$this->allow('tourism.events.create','/tourism/events'))return;$this->view('Tourism::Events.create',['title'=>'Add Event','providers'=>$this->s->providers((int)Auth::tenantId())]);}public function store(){if(!$this->allow('tourism.events.create','/tourism/events'))return;$t=(int)Auth::tenantId();try{$id=$this->s->save($t,null,$_POST,(int)Auth::id());flash('success','Event created.');redirect('/tourism/events/'.$id);}catch(Throwable $e){$this->view('Tourism::Events.create',['title'=>'Add Event','providers'=>$this->s->providers($t),'error'=>$e->getMessage(),'old'=>$_POST]);}}public function show($id){if(!$this->allow('tourism.events.view','/tourism/events'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('Tourism::Events.show',['title'=>$r['title'],'record'=>$r]);}public function edit($id){if(!$this->allow('tourism.events.edit','/tourism/events'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('Tourism::Events.edit',['title'=>'Edit Event','record'=>$r,'providers'=>$this->s->providers((int)Auth::tenantId())]);}public function update($id){if(!$this->allow('tourism.events.edit','/tourism/events'))return;$t=(int)Auth::tenantId();try{$this->s->save($t,$id,$_POST,(int)Auth::id());flash('success','Event updated.');redirect('/tourism/events/'.$id);}catch(Throwable $e){$this->view('Tourism::Events.edit',['title'=>'Edit Event','record'=>$this->s->find($t,$id)??$_POST,'providers'=>$this->s->providers($t),'error'=>$e->getMessage()]);}}public function destroy($id){if(!$this->allow('tourism.events.delete','/tourism/events'))return;$this->s->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Event moved to Trash.');redirect('/tourism/events');}public function restore($id){if(!$this->allow('tourism.events.delete','/tourism/events?view=trash'))return;$this->s->restore((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Event restored.');redirect('/tourism/events?view=trash');}}